#include "genesis/perception/persistence.hpp"
#include "genesis/runtime/runtime.hpp"
#include <bit>
#include <cctype>
#include <fstream>
#include <iterator>
#include <stdexcept>
namespace genesis::perception {namespace {
constexpr std::string_view magic="GENESIS-PERCEPTION";constexpr std::uint64_t schema=1,max_items=1000000,max_field=16U*1024U*1024U;
void err(PerceptionStoreError*e,PerceptionStoreErrorCode c,std::string m){if(e){e->code=c;e->message=std::move(m);}}void idok(std::string_view s){if(s.empty()||s.size()>128||s=="."||s=="..")throw std::invalid_argument("unsafe identifier");for(unsigned char c:s)if(!std::isalnum(c)&&c!='_'&&c!='-'&&c!='.')throw std::invalid_argument("unsafe identifier character");}void u64(std::string&o,std::uint64_t v){for(unsigned s=0;s<64;s+=8)o.push_back(static_cast<char>((v>>s)&255));}std::uint64_t get64(std::string_view b,std::size_t&o){if(o>b.size()||b.size()-o<8)throw std::runtime_error("truncated integer");std::uint64_t v=0;for(unsigned s=0;s<64;s+=8)v|=static_cast<std::uint64_t>(static_cast<unsigned char>(b[o++]))<<s;return v;}void str(std::string&o,std::string_view s){u64(o,s.size());o.append(s);}std::string getstr(std::string_view b,std::size_t&o){const auto n=get64(b,o);if(n>max_field||n>b.size()-o)throw std::runtime_error("invalid field length");std::string s(b.substr(o,n));o+=n;return s;}void dbl(std::string&o,double v){u64(o,std::bit_cast<std::uint64_t>(v));}double getdbl(std::string_view b,std::size_t&o){return std::bit_cast<double>(get64(b,o));}std::string readall(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot open perception record");std::string b{std::istreambuf_iterator<char>(f),{}};if(f.bad())throw std::runtime_error("cannot read perception record");return b;}
}
PerceptionStore::PerceptionStore(std::filesystem::path root,std::size_t maximum):root_(std::move(root)),maximum_record_bytes_(maximum){if(root_.empty()||maximum<1024)throw std::invalid_argument("invalid perception store configuration");}
std::string PerceptionStore::serialize(const PerceptionPipeline&p){if(!p.verify())throw std::invalid_argument("invalid perception pipeline");std::string o(magic);u64(o,schema);str(o,p.organism_id_);u64(o,p.route_capacity_);u64(o,p.observation_capacity_);u64(o,p.feature_capacity_);u64(o,p.policy_.minimum_successes);dbl(o,p.policy_.maximum_failure_rate);u64(o,p.routes_.size());for(const auto&[_,r]:p.routes_){str(o,r.id);str(o,r.provider_id);str(o,r.artifact_digest);str(o,r.license_id);str(o,r.declaration_evidence_digest);str(o,r.latest_probe_evidence_digest);str(o,r.qualification_evidence_digest);u64(o,static_cast<std::uint64_t>(r.modality));u64(o,static_cast<std::uint64_t>(r.state));u64(o,r.probes);u64(o,r.successes);u64(o,r.failures);u64(o,r.last_probe_at);}u64(o,p.observations_.size());for(const auto&[_,x]:p.observations_){str(o,x.id);str(o,x.route_id);str(o,x.payload_digest);str(o,x.provenance_digest);u64(o,x.captured_at);u64(o,x.received_at);dbl(o,x.confidence);dbl(o,x.uncertainty);}u64(o,p.features_.size());for(const auto&[_,x]:p.features_){str(o,x.id);str(o,x.observation_id);str(o,x.name);str(o,x.value_digest);str(o,x.derivation_digest);dbl(o,x.confidence);dbl(o,x.uncertainty);}o+=runtime::sha256(o);return o;}
std::optional<PerceptionPipeline> PerceptionStore::deserialize(std::string_view b,PerceptionStoreError*e){try{if(b.size()<magic.size()+8+64||b.substr(0,magic.size())!=magic)throw std::runtime_error("invalid perception magic");const auto payload=b.substr(0,b.size()-64);if(runtime::sha256(payload)!=b.substr(b.size()-64))throw std::runtime_error("perception checksum mismatch");std::size_t o=magic.size();if(get64(payload,o)!=schema){err(e,PerceptionStoreErrorCode::unsupported_schema,"unsupported perception schema");return std::nullopt;}auto owner=getstr(payload,o);const auto rc=get64(payload,o),oc=get64(payload,o),fc=get64(payload,o),minimum=get64(payload,o);const auto failure=getdbl(payload,o);if(!rc||!oc||!fc||rc>max_items||oc>max_items||fc>max_items)throw std::runtime_error("invalid perception capacities");PerceptionPipeline p(owner,rc,oc,fc,{minimum,failure});const auto routes=get64(payload,o);if(routes>rc)throw std::runtime_error("route count exceeds capacity");for(std::uint64_t n=0;n<routes;++n){AdapterRoute r;r.id=getstr(payload,o);r.provider_id=getstr(payload,o);r.artifact_digest=getstr(payload,o);r.license_id=getstr(payload,o);r.declaration_evidence_digest=getstr(payload,o);r.latest_probe_evidence_digest=getstr(payload,o);r.qualification_evidence_digest=getstr(payload,o);const auto modality=get64(payload,o),state=get64(payload,o);if(modality>static_cast<std::uint64_t>(Modality::custom)||state>static_cast<std::uint64_t>(RouteEvidenceState::qualified))throw std::runtime_error("invalid route enum");r.modality=static_cast<Modality>(modality);r.state=static_cast<RouteEvidenceState>(state);r.probes=get64(payload,o);r.successes=get64(payload,o);r.failures=get64(payload,o);r.last_probe_at=get64(payload,o);if(!p.routes_.emplace(r.id,std::move(r)).second)throw std::runtime_error("duplicate route");}const auto observations=get64(payload,o);if(observations>oc)throw std::runtime_error("observation count exceeds capacity");for(std::uint64_t n=0;n<observations;++n){RawObservation x;x.id=getstr(payload,o);x.route_id=getstr(payload,o);x.payload_digest=getstr(payload,o);x.provenance_digest=getstr(payload,o);x.captured_at=get64(payload,o);x.received_at=get64(payload,o);x.confidence=getdbl(payload,o);x.uncertainty=getdbl(payload,o);if(!p.observations_.emplace(x.id,std::move(x)).second)throw std::runtime_error("duplicate observation");}const auto features=get64(payload,o);if(features>fc)throw std::runtime_error("feature count exceeds capacity");for(std::uint64_t n=0;n<features;++n){DerivedFeature x;x.id=getstr(payload,o);x.observation_id=getstr(payload,o);x.name=getstr(payload,o);x.value_digest=getstr(payload,o);x.derivation_digest=getstr(payload,o);x.confidence=getdbl(payload,o);x.uncertainty=getdbl(payload,o);if(!p.features_.emplace(x.id,std::move(x)).second)throw std::runtime_error("duplicate feature");}if(o!=payload.size()||!p.verify())throw std::runtime_error("trailing or invalid perception data");err(e,PerceptionStoreErrorCode::none,{});return p;}catch(const std::exception&x){err(e,PerceptionStoreErrorCode::corrupt_record,x.what());return std::nullopt;}}
bool PerceptionStore::write(const PerceptionPipeline&p,std::string_view version,PerceptionStoreError*e)const{try{idok(p.organism_id());idok(version);auto bytes=serialize(p);if(bytes.size()>maximum_record_bytes_)throw std::invalid_argument("perception record exceeds configured limit");std::error_code ec;std::filesystem::create_directories(root_,ec);if(ec)throw std::runtime_error("cannot create perception store");const auto target=root_/(p.organism_id()+"."+std::string(version)+".perception");if(std::filesystem::exists(target)){if(readall(target)==bytes){err(e,PerceptionStoreErrorCode::none,{});return true;}err(e,PerceptionStoreErrorCode::conflicting_version,"immutable perception version conflict");return false;}const auto temp=std::filesystem::path(target.string()+".tmp-"+runtime::sha256(bytes));{std::ofstream f(temp,std::ios::binary|std::ios::trunc);f.write(bytes.data(),static_cast<std::streamsize>(bytes.size()));f.flush();if(!f)throw std::runtime_error("cannot flush perception record");}std::filesystem::rename(temp,target,ec);if(ec){std::filesystem::remove(temp);throw std::runtime_error("cannot atomically commit perception record");}err(e,PerceptionStoreErrorCode::none,{});return true;}catch(const std::invalid_argument&x){err(e,PerceptionStoreErrorCode::invalid_pipeline,x.what());return false;}catch(const std::exception&x){err(e,PerceptionStoreErrorCode::io_error,x.what());return false;}}
std::optional<PerceptionPipeline> PerceptionStore::read(std::string_view owner,std::string_view version,PerceptionStoreError*e)const{try{idok(owner);idok(version);const auto path=root_/(std::string(owner)+"."+std::string(version)+".perception");if(!std::filesystem::exists(path)){err(e,PerceptionStoreErrorCode::not_found,"perception record not found");return std::nullopt;}const auto bytes=readall(path);if(bytes.size()>maximum_record_bytes_){err(e,PerceptionStoreErrorCode::corrupt_record,"perception record exceeds configured limit");return std::nullopt;}auto p=deserialize(bytes,e);if(p&&p->organism_id()!=owner){err(e,PerceptionStoreErrorCode::corrupt_record,"perception owner mismatch");return std::nullopt;}return p;}catch(const std::invalid_argument&x){err(e,PerceptionStoreErrorCode::invalid_identifier,x.what());return std::nullopt;}catch(const std::exception&x){err(e,PerceptionStoreErrorCode::io_error,x.what());return std::nullopt;}}
}
